string text = "The qick brown fox jumps over the lazy dog";
string toReplace = "qick";
int found = text.find(toReplace);   // 4
if (found >= 0) {
    text.replace(found, toReplace.length(), "quick");
    cout << text;   // The quick brown fox ...
} else
