#include <iostream>
#include <cstring>
using namespace std;
int main()
{   char input[1000];
    cout << "Введите строку: ";
    cin.getline(input, 1000);
    int count = 0;
    int length = strlen(input);
    for (int i = 0; i < length; i++)
        if (input[i] == '.' || input[i] == '!' || input[i] == '?')
            count++;
    cout << "Количество предложений: " << count << endl;
    return 0; }

